package local.zft;
import android.app.Activity;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.*;

public final class AiActivity extends Activity {
 private LinearLayout root,feed,rows,reader;private TextView status,more,refresh;private AiArticle article;private int detailGeneration;private boolean readerLoading;private ScrollView scroll;
 private final TextView[] tabs=new TextView[2];private final Set<String> ids=new HashSet<>();private final Set<String> identities=new HashSet<>();
 private int mode,generation;private boolean loading,appendFailed;private String cursor="";private SharedPreferences cache;
 private android.window.OnBackInvokedCallback systemBack;
 public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xfffafbf9);getWindow().setNavigationBarColor(-1);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  cache=getSharedPreferences("local.zft.aihot",0);root=Ui.column(this);root.setFitsSystemWindows(true);root.setBackgroundColor(0xfffafbf9);
  feed=Ui.column(this);LinearLayout header=new LinearLayout(this);TextView title=label("AI 动态",26,Ui.INK);title.setTypeface(null,1);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));refresh=button("↻",()->load(false));refresh.setTextSize(27);refresh.setContentDescription("刷新资讯");header.addView(refresh);feed.addView(header);TextView subtitle=label("追踪 AI 热点，发现值得读的事",12,Ui.MUTED);subtitle.setPadding(Ui.dp(this,20),0,0,Ui.dp(this,14));feed.addView(subtitle);
  LinearLayout segments=new LinearLayout(this);segments.setPadding(Ui.dp(this,12),0,Ui.dp(this,12),0);for(int i=0;i<2;i++){final int index=i;tabs[i]=button(i==0?"热点榜":"精选",()->select(index));tabs[i].setTag("ai.mode."+i);segments.addView(tabs[i],new LinearLayout.LayoutParams(Ui.dp(this,100),Ui.dp(this,44)));}feed.addView(segments);
  status=label("",11,Ui.MUTED);status.setTag("ai.status");feed.addView(status);scroll=new ScrollView(this);scroll.setTag("ai.scroll");rows=Ui.column(this);rows.setPadding(Ui.dp(this,20),0,Ui.dp(this,20),0);rows.setTag("ai.rows");LinearLayout content=Ui.column(this);content.addView(rows);scroll.addView(content);feed.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  more=button("加载失败，点击重试",()->load(true));more.setTag("ai.more");more.setVisibility(View.GONE);content.addView(more);
  scroll.setOnScrollChangeListener((v,x,y,oldX,oldY)->{if(y>oldY&&!appendFailed&&reader==null&&scroll.isShown()&&content.getHeight()-y-scroll.getHeight()<=Ui.dp(this,120))load(true);});
  root.addView(feed,new LinearLayout.LayoutParams(-1,0,1));root.addView(Ui.navigation(this,4,i->ChatHome.navigate(this,i)));setContentView(root);
  if(Build.VERSION.SDK_INT>=33){systemBack=this::onBackPressed;getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,systemBack);}select(0);
 }
 private TextView label(String text,int size,int color){TextView v=Ui.text(this,text,size,color);v.setPadding(Ui.dp(this,20),Ui.dp(this,10),Ui.dp(this,20),Ui.dp(this,10));return v;}
 private TextView button(String text,Runnable action){TextView v=label(text,15,Ui.ACCENT);v.setGravity(Gravity.CENTER);v.setMinHeight(Ui.dp(this,48));v.setFocusable(true);v.setOnClickListener(w->action.run());return v;}
 private void select(int next){mode=next;generation++;loading=false;appendFailed=false;cursor="";scroll.scrollTo(0,0);ids.clear();identities.clear();rows.removeAllViews();for(int i=0;i<2;i++){tabs[i].setSelected(i==mode);tabs[i].setBackground(Ui.shape(this,i==mode?0xff202f2d:0xfffafbf9,22));tabs[i].setTextColor(i==mode?-1:Ui.MUTED);tabs[i].setTextSize(14);tabs[i].setTypeface(null,i==mode?1:0);}more.setVisibility(View.GONE);refresh.setEnabled(true);
  try{JSONObject saved=new JSONObject(cache.getString("feed."+mode,""));render(saved,false);status.setText(cacheTime()+" 更新 · 热点持续追踪");}catch(Exception ignored){status.setText("正在获取 AI 动态…");}
  if(ids.isEmpty()||System.currentTimeMillis()-cache.getLong("time."+mode,0)>300000)load(false);
 }
 private String cacheTime(){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("MM-dd HH:mm",Locale.CHINA);f.setTimeZone(TimeZone.getTimeZone("Asia/Shanghai"));return f.format(new Date(cache.getLong("time."+mode,0)));}
 private void load(boolean append){if(loading||(append&&cursor.isEmpty()))return;loading=true;appendFailed=false;refresh.setEnabled(false);more.setEnabled(false);more.setText("正在加载…");more.setVisibility(append?View.VISIBLE:View.GONE);status.setText(append?"正在加载更多…":"正在更新…");final int token=++generation,selected=mode;final String after=append?cursor:"";
  new Thread(()->{try{JSONObject data=fetch(selected,after);runOnUiThread(()->{if(isDestroyed()||token!=generation)return;try{render(data,append);if(!append)cache.edit().putString("feed."+selected,data.toString()).putLong("time."+selected,System.currentTimeMillis()).apply();status.setText(cacheTime()+" 更新 · "+(mode==0?"多来源聚合":"为你筛选值得读的内容"));}catch(Exception e){failed(append,"数据暂不可用，请刷新重试");}finishLoad();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||token!=generation)return;failed(append,(ids.isEmpty()?"暂时无法加载":"已保留当前内容")+" · 请检查网络后刷新");finishLoad();});}},"aihot-feed").start();
 }
 private void failed(boolean append,String message){status.setText(message);appendFailed=append;more.setText("加载失败，点击重试");}
 private void finishLoad(){loading=false;refresh.setEnabled(true);more.setEnabled(appendFailed);more.setVisibility(appendFailed?View.VISIBLE:View.GONE);}
 static JSONObject fetch(int mode,String cursor)throws Exception{
  String path=mode==0?"hot-topics":"items?mode=selected&limit=20"+(cursor.isEmpty()?"":"&cursor="+URLEncoder.encode(cursor,"UTF-8"));
  JSONObject data=request(path);data.getJSONArray("items");return data;
 }
 private static JSONObject request(String path)throws Exception{
  HttpURLConnection c=(HttpURLConnection)new URL("https://aihot.news"+(path.startsWith("/api/site/items/")?path:"/api/v1/"+path)).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","aihot-api/2.0.0");c.setRequestProperty("Accept","application/json");
  try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2000000)throw new IOException("Feed too large");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}
 }
 static String articleUrl(JSONObject item){JSONObject links=item.optJSONObject("links");if(links==null)return "";String link=links.optString("story","");if(link.isEmpty())link=links.optString("aihot","");try{URI u=new URI(link);String host=u.getHost();if(!"https".equals(u.getScheme())||u.getUserInfo()!=null||u.getPort()!=-1||!("aihot.news".equals(host)||"aihot.virxact.com".equals(host)))return "";return new URI("https",null,"aihot.news",-1,u.getPath(),u.getQuery(),u.getFragment()).toString();}catch(Exception e){return "";}}
 private void render(JSONObject data,boolean append)throws Exception{JSONArray items=data.getJSONArray("items");if(!append){rows.removeAllViews();ids.clear();identities.clear();}for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String id=item.optString("id",""),url=articleUrl(item),title=item.optString("title","");if(id.isEmpty()||title.isEmpty()||url.isEmpty()||ids.contains(id))continue;String titleKey="title:"+title.trim().toLowerCase(Locale.ROOT);JSONObject links=item.optJSONObject("links");String original=links==null?"":text(links,"original");if(identities.contains(titleKey)||(!original.isEmpty()&&identities.contains("url:"+original)))continue;ids.add(id);identities.add(titleKey);if(!original.isEmpty())identities.add("url:"+original);
   LinearLayout row=new LinearLayout(this);row.setPadding(0,Ui.dp(this,18),0,Ui.dp(this,18));
   if(mode==0){int rank=item.optInt("rank",i+1);TextView number=Ui.text(this,String.format(Locale.ROOT,"%02d",rank),23,rank<=3?0xffdc673e:0xffa8b3b0);number.setTypeface(android.graphics.Typeface.create("sans-serif-condensed",1));number.setGravity(Gravity.TOP);row.addView(number,new LinearLayout.LayoutParams(Ui.dp(this,42),-1));}
   LinearLayout content=Ui.column(this);row.addView(content,new LinearLayout.LayoutParams(0,-2,1));TextView headline=Ui.text(this,title,16,Ui.INK);headline.setTypeface(null,1);headline.setMaxLines(2);headline.setEllipsize(android.text.TextUtils.TruncateAt.END);headline.setLineSpacing(Ui.dp(this,3),1);content.addView(headline);
   String summary=item.optString("summary","");if(!summary.isEmpty()&&!"null".equals(summary)&&!summary.trim().equals(title.trim())){TextView body=Ui.text(this,summary,13,Ui.MUTED);body.setPadding(0,Ui.dp(this,7),0,0);body.setLineSpacing(Ui.dp(this,3),1);body.setMaxLines(1);body.setEllipsize(android.text.TextUtils.TruncateAt.END);content.addView(body);}
   JSONObject source=item.optJSONObject("source");String meta=source==null?"AIHOT":source.optString("name","AIHOT");meta=meta.replace("公众号：","").replace(" · Blog（网页）","");
   LinearLayout byline=new LinearLayout(this);byline.setGravity(Gravity.CENTER_VERTICAL);byline.setPadding(0,Ui.dp(this,10),0,0);TextView origin=Ui.text(this,meta,11,Ui.MUTED);origin.setSingleLine(true);origin.setEllipsize(android.text.TextUtils.TruncateAt.END);byline.addView(origin,new LinearLayout.LayoutParams(0,-2,1));if(mode==0){TextView count=Ui.text(this,item.optInt("sourceCount")+" 个来源",10,Ui.ACCENT);count.setPadding(Ui.dp(this,7),Ui.dp(this,3),Ui.dp(this,7),Ui.dp(this,3));count.setBackground(Ui.shape(this,0xffeaf2ee,5));byline.addView(count);}content.addView(byline);
   row.setContentDescription(title+"，阅读详情");row.setFocusable(true);row.setOnClickListener(v->openArticle(item));rows.addView(row,new LinearLayout.LayoutParams(-1,-2));View line=new View(this);line.setBackgroundColor(0xffe7ebe8);rows.addView(line,new LinearLayout.LayoutParams(-1,Ui.dp(this,1)));

  }JSONObject page=data.optJSONObject("page");cursor=mode==1&&page!=null&&page.optBoolean("hasMore")?page.optString("nextCursor",""):"";more.setVisibility(View.GONE);if(ids.isEmpty())rows.addView(label("暂时没有内容，稍后刷新看看",15,Ui.MUTED));
 }
 private void openArticle(JSONObject item){if(reader!=null)return;reader=Ui.column(this);reader.setTag("ai.reader");TextView back=button("‹ 返回",()->closeArticle());back.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);back.setPadding(Ui.dp(this,24),0,Ui.dp(this,24),0);back.setMinHeight(Ui.dp(this,52));reader.addView(back);ScrollView reading=new ScrollView(this);reading.setVerticalScrollBarEnabled(false);LinearLayout body=Ui.column(this);body.setTag("ai.article");body.setPadding(0,Ui.dp(this,16),0,Ui.dp(this,40));reading.addView(body);reader.addView(reading,new LinearLayout.LayoutParams(-1,0,1));feed.setVisibility(View.GONE);root.findViewWithTag("local.zft.tabs").setVisibility(View.GONE);root.addView(reader,0,new LinearLayout.LayoutParams(-1,0,1));
  TextView title=label(item.optString("title"),26,Ui.INK);title.setTag("ai.article.title");title.setTypeface(null,1);title.setLineSpacing(Ui.dp(this,4),1);title.setPadding(Ui.dp(this,24),0,Ui.dp(this,24),Ui.dp(this,16));body.addView(title);
  String url=articleUrl(item);String path=android.net.Uri.parse(url).getPath();if(path!=null&&path.matches("/story/[A-Za-z0-9-]+")){loadStory(body,path.substring(7));}else{JSONObject source=item.optJSONObject("source");if(source!=null){TextView byline=label(source.optString("name"),12,Ui.MUTED);byline.setPadding(Ui.dp(this,24),0,Ui.dp(this,24),Ui.dp(this,20));body.addView(byline);}loadItem(body,item.optString("id"));}
 }
 // shortcut: the site detail API is unversioned; revisit if its body/media contract changes.
 private void loadItem(LinearLayout body,String id){if(!id.matches("[A-Za-z0-9_-]{1,80}")){body.addView(label("文章标识无效",14,Ui.MUTED));return;}final int token=++detailGeneration;readerLoading=true;TextView state=label("正在加载完整正文…",14,Ui.MUTED);body.addView(state);new Thread(()->{try{JSONObject data=request("/api/site/items/"+id);if(!id.equals(data.optString("id")))throw new IOException("Article mismatch");runOnUiThread(()->{if(isDestroyed()||reader==null||token!=detailGeneration)return;readerLoading=false;body.removeView(state);article=new AiArticle(this);article.render(data);body.addView(article);});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||reader==null||token!=detailGeneration)return;readerLoading=false;state.setText("正文加载失败，点击重试");state.setOnClickListener(v->{body.removeView(state);loadItem(body,id);});});}},"aihot-article").start();}
 private static String text(JSONObject o,String key){return o.isNull(key)?"":o.optString(key,"");}
 private void paragraph(LinearLayout body,String heading,String value){if(value.trim().isEmpty())return;TextView h=label(heading,12,Ui.MUTED);h.setPadding(Ui.dp(this,24),Ui.dp(this,8),Ui.dp(this,24),Ui.dp(this,8));body.addView(h);TextView t=label(value,17,Ui.INK);t.setPadding(Ui.dp(this,24),Ui.dp(this,12),Ui.dp(this,24),Ui.dp(this,18));t.setLineSpacing(Ui.dp(this,3),1.25f);t.setTextIsSelectable(true);body.addView(t);}
 private void loadStory(LinearLayout body,String id){final int token=++detailGeneration;readerLoading=true;LinearLayout detail=Ui.column(this);body.addView(detail);detail.addView(label("正在加载事件综述…",14,Ui.MUTED));new Thread(()->{try{JSONObject story=request("stories/"+id).getJSONObject("story");runOnUiThread(()->{if(isDestroyed()||reader==null||token!=detailGeneration)return;readerLoading=false;detail.removeAllViews();String digest=text(story,"digest");paragraph(detail,"事件综述",digest.isEmpty()?text(story,"latest"):digest);JSONArray reports=story.optJSONArray("reports");if(reports!=null){Set<String> sources=new LinkedHashSet<>();for(int i=0;i<reports.length();i++){JSONObject report=reports.optJSONObject(i);JSONObject source=report==null?null:report.optJSONObject("source");if(source!=null&&!text(source,"name").isEmpty())sources.add(text(source,"name"));}if(!sources.isEmpty()){TextView attribution=label("综合 "+sources.size()+" 个来源",12,Ui.MUTED);detail.addView(attribution);}}});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||reader==null||token!=detailGeneration)return;readerLoading=false;detail.removeAllViews();detail.addView(button("暂时无法加载，点击重试",()->{body.removeView(detail);loadStory(body,id);}));});}},"aihot-story").start();}
 private void closeArticle(){if(article!=null){article.close();article=null;}detailGeneration++;readerLoading=false;if(reader==null)return;root.removeView(reader);reader=null;feed.setVisibility(View.VISIBLE);root.findViewWithTag("local.zft.tabs").setVisibility(View.VISIBLE);}
 public void onBackPressed(){if(reader!=null)closeArticle();else finish();}
 public void onDestroy(){generation++;if(Build.VERSION.SDK_INT>=33&&systemBack!=null)getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(systemBack);closeArticle();super.onDestroy();}
}
